local CeremonialSashMaker = {}
local PRODUCTS = {
    simple_silk_sash = { name = "Preprost svileni pas", silkCost = 2, threadCost = 1, time = 3, cost = 60, prestige = 4, happiness = 2, description = "Preprost svileni pas za slovesnosti." },
    silver_embroidered_sash = { name = "Srebrnovezeni pas", silkCost = 2, silverCost = 1, threadCost = 1, time = 6, cost = 180, prestige = 10, happiness = 3, description = "Srebrnovezeni pas za trgovce." },
    gold_woven_sash = { name = "Zlatopleteni pas", silkCost = 3, goldCost = 1, silverCost = 1, threadCost = 1, time = 9, cost = 440, prestige = 20, happiness = 4, description = "Zlatopleteni pas za plemiče." },
    jewel_pinned_sash = { name = "Draguljnoprity pas", silkCost = 3, goldCost = 1, silverCost = 1, threadCost = 1, jewelCost = 1, time = 13, cost = 1000, prestige = 32, happiness = 6, description = "Pas z draguljno priponko za visoke plemiče." },
    pearl_set_sash = { name = "Bisernavi pas", silkCost = 3, goldCost = 2, silverCost = 1, threadCost = 1, jewelCost = 1, pearlCost = 1, time = 17, cost = 2200, prestige = 48, happiness = 8, description = "Pas z biseri za visoko plemstvo." },
    royal_grand_sash = { name = "Kraljevski veliki pas", silkCost = 5, goldCost = 3, silverCost = 2, threadCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 5000, prestige = 70, happiness = 13, description = "Veliki kraljevski pas z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    sash_workshop = { name = "Pasna delavnica", cost = { gold = 260, wood = 120, stone = 120, silk = 6, thread = 6 }, upkeep = 6, qualityBonus = 5 },
    ceremonial_loft = { name = "Slovesna podstrešje", cost = { gold = 950, wood = 280, stone = 240, silver = 6, gold = 4 }, upkeep = 22, qualityBonus = 18 },
    master_sash_atelier = { name = "Mojstrski pasni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_ceremony_palace = { name = "Kraljevska slovesna palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
CeremonialSashMaker.silkStock = 14; CeremonialSashMaker.threadStock = 12; CeremonialSashMaker.silverStock = 6; CeremonialSashMaker.goldStock = 6; CeremonialSashMaker.jewelStock = 4; CeremonialSashMaker.pearlStock = 4
CeremonialSashMaker.productStock = {}; CeremonialSashMaker.buildings = {}; CeremonialSashMaker.maker = nil; CeremonialSashMaker.activeMaking = {}; CeremonialSashMaker.totalProducts = 0; CeremonialSashMaker.dayTimer = 0
function CeremonialSashMaker.init() CeremonialSashMaker.silkStock=14; CeremonialSashMaker.threadStock=12; CeremonialSashMaker.silverStock=6; CeremonialSashMaker.goldStock=6; CeremonialSashMaker.jewelStock=4; CeremonialSashMaker.pearlStock=4; CeremonialSashMaker.productStock={}; CeremonialSashMaker.buildings={}; CeremonialSashMaker.maker=nil; CeremonialSashMaker.activeMaking={}; CeremonialSashMaker.totalProducts=0; CeremonialSashMaker.dayTimer=0; print("[CeremonialSashMaker] Royal Ceremonial Sash Maker System initialized (6 products, 4 buildings)") end
function CeremonialSashMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CeremonialSashMaker.maker={name=n or ("Pasar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pasar najet: %s (spretnost: %d)",CeremonialSashMaker.maker.name,s),"success") end; return true end
function CeremonialSashMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CeremonialSashMaker.build(id) local ok,e=CeremonialSashMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CeremonialSashMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CeremonialSashMaker.getQualityBonus() local b=0; for _,bd in ipairs(CeremonialSashMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CeremonialSashMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and CeremonialSashMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.threadCost and CeremonialSashMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.silverCost and CeremonialSashMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CeremonialSashMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CeremonialSashMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CeremonialSashMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CeremonialSashMaker.buildings==0 then return false,"Potrebna pasna delavnica" end; if not CeremonialSashMaker.maker then return false,"Potreben pasar" end; return true end
function CeremonialSashMaker.make(pt,qty) qty=qty or 1; local ok,e=CeremonialSashMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then CeremonialSashMaker.silkStock=CeremonialSashMaker.silkStock-d.silkCost*qty end; if d.threadCost then CeremonialSashMaker.threadStock=CeremonialSashMaker.threadStock-d.threadCost*qty end; if d.silverCost then CeremonialSashMaker.silverStock=CeremonialSashMaker.silverStock-d.silverCost*qty end; if d.goldCost then CeremonialSashMaker.goldStock=CeremonialSashMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CeremonialSashMaker.jewelStock=CeremonialSashMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CeremonialSashMaker.pearlStock=CeremonialSashMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CeremonialSashMaker.maker then t=math.max(1,t-math.floor(CeremonialSashMaker.maker.skill/13)) end; table.insert(CeremonialSashMaker.activeMaking,{id="ceremonialsash_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šivanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CeremonialSashMaker.completeMaking(m) local q=1.0+(CeremonialSashMaker.getQualityBonus()/100); if CeremonialSashMaker.maker then q=q+(CeremonialSashMaker.maker.skill/140) end; q=math.min(2.5,q); CeremonialSashMaker.productStock[m.productType]=(CeremonialSashMaker.productStock[m.productType] or 0)+m.quantity; CeremonialSashMaker.totalProducts=CeremonialSashMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CeremonialSashMaker.maker then CeremonialSashMaker.maker.itemsMade=CeremonialSashMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CeremonialSashMaker.maker.skill=math.min(100,CeremonialSashMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pas izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ceremonialsash.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CeremonialSashMaker.update(dt) if not _G.state then return end; CeremonialSashMaker.dayTimer=CeremonialSashMaker.dayTimer+dt; if CeremonialSashMaker.dayTimer>=30 then CeremonialSashMaker.dayTimer=0; for i=#CeremonialSashMaker.activeMaking,1,-1 do local m=CeremonialSashMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CeremonialSashMaker.completeMaking(m); table.remove(CeremonialSashMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CeremonialSashMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CeremonialSashMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CeremonialSashMaker.getStats() return {silkStock=CeremonialSashMaker.silkStock,threadStock=CeremonialSashMaker.threadStock,silverStock=CeremonialSashMaker.silverStock,goldStock=CeremonialSashMaker.goldStock,jewelStock=CeremonialSashMaker.jewelStock,pearlStock=CeremonialSashMaker.pearlStock,productStock=CeremonialSashMaker.productStock,numBuildings=#CeremonialSashMaker.buildings,hasMaker=CeremonialSashMaker.maker~=nil,makerName=CeremonialSashMaker.maker and CeremonialSashMaker.maker.name or "—",makerSkill=CeremonialSashMaker.maker and CeremonialSashMaker.maker.skill or 0,activeMaking=#CeremonialSashMaker.activeMaking,totalProducts=CeremonialSashMaker.totalProducts} end
return CeremonialSashMaker
